def numberOfSpecialLetters(word: str) -> int:
    # Create sets for lowercase and uppercase letters in the word
    lowercase_set = set()
    uppercase_set = set()

    # Iterate through each character in the word
    for char in word:
        if char.islower():
            lowercase_set.add(char)
        else:
            uppercase_set.add(char.lower())  # Convert to lowercase for comparison

    # Find the intersection of both sets - these are the special letters
    special_letters = lowercase_set & uppercase_set

    # Return the count of special letters
