def longestCommonPrefix(arr1, arr2):
    # Convert all numbers in arr1 to their string representations and store all prefixes
    prefixes = set()
    for num in arr1:
        s = str(num)
        # Add all prefixes of this number
        for i in range(1, len(s) + 1):
            prefixes.add(s[:i])

    max_length = 0

    # Check each number in arr2 for common prefixes
    for num in arr2:
        s = str(num)
        # Check all prefixes of this number
        for i in range(1, len(s) + 1):
