def punishmentNumber(n: int) -> int:
    def can_partition(s: str, target: int) -> bool:
        """Check if string s can be partitioned into contiguous substrings 
        such that the sum of their integer values equals target."""
        def backtrack(pos: int, current_sum: int) -> bool:
            if pos == len(s):
                return current_sum == target

            num = 0
            for i in range(pos, len(s)):
                num = num * 10 + int(s[i])
                # Early termination if current sum exceeds target
                if current_sum + num > target:
                    break
                if backtrack(i + 1, current_sum + num):
                    return True
            return False

        return backtrack(0, 0)

    total = 0
    for i in range(1, n + 1):
        square = i * i
        if can_partition(str(square), i):
            total += square

    return total
```

