def beautifulIndices(s: str, a: str, b: str, k: int) -> list[int]:
    # Find all indices where string 'a' appears in 's'
    a_indices = []
    for i in range(len(s) - len(a) + 1):
        if s[i:i + len(a)] == a:
            a_indices.append(i)

    # Find all indices where string 'b' appears in 's'
    b_indices = []
    for j in range(len(s) - len(b) + 1):
        if s[j:j + len(b)] == b:
            b_indices.append(j)

    # For each index i in a_indices, check if there exists a j in b_indices such that |j - i| <= k
    result = []
    # Use binary search for efficiency since b_indices is sorted
    import bisect

    for i in a_indices:
        # Find the position where i would be inserted in b_indices
        pos = bisect.bisect_left(b_indices, i)

        # Check the closest elements: the one at pos and the one at pos-1
        found = False

        # Check element at pos (if exists)
        if pos < len(b_indices):
            if abs(b_indices[pos] - i) <= k:
                found = True

        # Check element at pos-1 (if exists)
        if not found and pos > 0:
            if abs(b_indices[pos - 1] - i) <= k:
                found = True

        if found:
            result.append(i)

    return result
