def lastVisitedIntegers(words):
    nums = []  # List to store visited integers
    result = []  # List to store last visited integers for each "prev"
    consecutive_prevs = 0  # Count of consecutive "prev" strings

    for word in words:
        if word == "prev":
            consecutive_prevs += 1
            # If we have enough integers, get the (consecutive_prevs - 1)th from the end
            if consecutive_prevs <= len(nums):
                result.append(nums[-consecutive_prevs])
            else:
