def countMatchingSubarrays(nums, pattern):
    n = len(nums)
    m = len(pattern)

    count = 0

    # Iterate through all possible starting indices for subarrays of size m+1
    for i in range(n - m):
        # Check if the subarray nums[i:i+m+1] matches the pattern
        matches = True
        for k in range(m):
            if pattern[k] == 1:
                if nums[i + k + 1] <= nums[i + k]:
                    matches = False
                    break
            elif pattern[k] == 0:
                if nums[i + k + 1] != nums[i + k]:
                    matches = False
                    break
            else:  # pattern[k] == -1
                if nums[i + k + 1] >= nums[i + k]:
                    matches = False
                    break

        if matches:
            count += 1

    return count
