def maximumPrimeDifference(nums):
    # Helper function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        # Check odd divisors up to sqrt(n)
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find the first and last occurrence of prime numbers
    first_prime_index = -1
    last_prime_index = -1

    for i, num in enumerate(nums):
        if is_prime(num):
            if first_prime_index == -1:
                first_prime_index = i
            last_prime_index = i

    # Return the maximum distance between any two prime indices
    # Since we want the maximum distance, it's always between the first and last prime indices
    return last_prime_index - first_prime_index
